def apply(inputs, premises):
    kind = inputs["statement_kind"]
    answer = "NotMentioned"
    if kind == "employee_sharing":
        if bool(premises["employee_sharing_permitted"]):
            answer = "Entailment"
        elif bool(premises["employee_sharing_prohibited"]):
            answer = "Contradiction"
    if kind == "representative_sharing":
        if bool(premises["representative_sharing_permitted"]):
            answer = "Entailment"
        elif bool(premises["representative_sharing_prohibited"]):
            answer = "Contradiction"
    if kind == "termination_return_or_destroy":
        trigger = premises["disposition_trigger"]
        scope = premises["disposition_scope"]
        if trigger == "termination" or trigger == "both":
            answer = "Entailment"
        elif trigger == "request" and scope == "all_materials":
            answer = "Entailment"
        elif bool(premises["termination_disposition_prohibited"]):
            answer = "Contradiction"
    if kind == "post_disposition_retention":
        if bool(premises["post_disposition_retention_permitted"]):
            answer = "Entailment"
        elif bool(premises["post_disposition_retention_prohibited"]) or premises["disposition_scope"] == "all_materials":
            answer = "Contradiction"
    return {"answer": answer}

def apply(inputs, premises):
    names = inputs["asset_descriptions"]
    values = inputs["asset_values"]
    systems = inputs["applicable_exemption_systems"]
    asset_indices = premises["claim_asset_indices"]
    claim_systems = premises["claim_systems"]
    citations = premises["claim_citations"]
    caps = premises["claim_caps"]
    claims = {}
    for i in range(len(names)):
        claims[names[i]] = []
    for j in range(len(citations)):
        index = int(asset_indices[j])
        if index >= 0 and index < len(names) and claim_systems[j] in systems:
            cap = float(caps[j])
            claim_value = float(values[index])
            if cap >= 0:
                claim_value = min(claim_value, cap)
            claims[names[index]] = claims[names[index]] + [{"citation": citations[j], "claim_value": claim_value}]
    return {"asset_descriptions": names, "claims": claims}
